// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Interface describing `sicif`.
*/
interface Sicif {
	/**
	* Computes the sine and cosine integrals in single-precision floating-point format.
	*
	* @param x - input value
	* @returns output array
	*
	* @example
	* var v = sicif( 3.0 );
	* // returns [ ~1.849, ~0.12 ]
	*
	* @example
	* var v = sicif( 0.0 );
	* // returns [ 0.0, -Infinity ]
	*
	* @example
	* var v = sicif( -9.0 );
	* // returns [ ~-1.665, ~0.055 ]
	*
	* @example
	* var v = sicif( NaN );
	* // returns [ NaN, NaN ]
	*/
	( x: number ): Array<number>;

	/**
	* Computes the sine and cosine integrals in single-precision floating-point format and assigns results to a provided output array.
	*
	* @param x - input value
	* @param out - output array
	* @param stride - output array stride
	* @param offset - output array index offset
	* @returns output array
	*
	* @example
	* var Float32Array = require( '@stdlib/array/float32' );
	*
	* var out = new Float32Array( 2 );
	*
	* var v = sicif.assign( 3.0, out, 1, 0 );
	* // returns <Float32Array>[ ~1.849, ~0.12 ]
	*
	* var bool = ( v === out );
	* // returns true
	*/
	assign<T = unknown>( x: number, out: Collection<T>, stride: number, offset: number ): Collection<T | number>;
}

/**
* Computes the sine and cosine integrals in single-precision floating-point format.
*
* @param x - input value
* @returns output array
*
* @example
* var v = sicif( 3.0 );
* // returns [ ~1.849, ~0.12 ]
*
* @example
* var v = sicif( 0.0 );
* // returns [ 0.0, -Infinity ]
*
* @example
* var v = sicif( -9.0 );
* // returns [ ~-1.665, ~0.055 ]
*
* @example
* var v = sicif( NaN );
* // returns [ NaN, NaN ]
*/
declare var sicif: Sicif;


// EXPORTS //

export = sicif;
